-- Extrait de appareils.db pour les tests du rapprochement des fiches
-- Généré par scripts/extraire_base_fiches_test.py : ne pas modifier à la main.
BEGIN TRANSACTION;
CREATE TABLE appareils (
                    id INTEGER PRIMARY KEY,
                    type TEXT,
                    manufacturer TEXT,
                    ref_modele TEXT,
                    commercial_ref TEXT,
                    other_ref TEXT,
                    category TEXT,
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE piece_associations (
    id INTEGER PRIMARY KEY,
    piece_id INTEGER NOT NULL,
    appareil_id INTEGER NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(piece_id) REFERENCES pieces(id) ON DELETE CASCADE,
    FOREIGN KEY(appareil_id) REFERENCES appareils(id) ON DELETE CASCADE,
    UNIQUE(piece_id, appareil_id)
);
CREATE TABLE piece_equivalence_groups (
                    group_id  INTEGER NOT NULL,
                    ref_piece TEXT NOT NULL,
                    PRIMARY KEY (group_id, ref_piece),
                    FOREIGN KEY (ref_piece) REFERENCES pieces(ref_piece) ON DELETE CASCADE
                );
CREATE TABLE piece_supersessions (
                    ref_old  TEXT NOT NULL,
                    ref_new  TEXT,
                    PRIMARY KEY (ref_old),
                    FOREIGN KEY (ref_old) REFERENCES pieces(ref_piece) ON DELETE CASCADE,
                    FOREIGN KEY (ref_new) REFERENCES pieces(ref_piece) ON DELETE SET NULL
                );
CREATE TABLE pieces (
    id INTEGER PRIMARY KEY,
    ref_piece TEXT NOT NULL UNIQUE,
    description TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, is_obsolete INTEGER NOT NULL DEFAULT 0, is_phantom INTEGER NOT NULL DEFAULT 0);
CREATE TABLE reference_decisions (
                    ref_modele TEXT PRIMARY KEY,
                    decision TEXT CHECK(decision IN ('DISTINCT', 'MERGE')) NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    notes TEXT
                );
COMMIT;
